import{_ as e,c as r,o as p,ae as n}from"./chunks/framework.C-JRAr_X.js";const t="data:image/png;base64,",s="/NEWTEST/assets/6._%EA%B5%AD%EC%99%B8%EC%97%AC%ED%96%89_%EC%97%85%EB%AC%B4_%EB%A7%A4%EB%89%B4%EC%96%BC-image2.BLwS9qJX.jpeg",h=JSON.parse('{"title":"6. 국외여행 업무 매뉴얼","description":"","frontmatter":{"title":"6. 국외여행 업무 매뉴얼"},"headers":[],"relativePath":"manual/6._국외여행_업무_매뉴얼.md","filePath":"manual/6._국외여행_업무_매뉴얼.md"}'),o={name:"manual/6._국외여행_업무_매뉴얼.md"};function g(i,l,d,a,u,c){return p(),r("div",null,l[0]||(l[0]=[n('<table><colgroup><col style="width:16%;"><col style="width:83%;"></colgroup><thead><tr><th><p><strong>식비</strong></p></th><th><ul><li><p>여행일수에 따라 정액 지급하며, 정산 불필요</p></li><li><p>식사를 제공하는 이동수단에서의 식사는 산정 시 제외</p></li><li><p>국가 및 도시등급별 지급액 상이</p></li><li><p>여행자 계좌로 지급하며, 본인이 직접 지출결의 진행</p></li></ul></th></tr></thead><tbody><tr><td><p><strong>일비</strong></p></td><td><ul><li><p>여행일수에 따라 정액 지급하며, 정산 불필요</p></li><li><p>항공마일리지 사용 시 1일 당 일비의 50% 추가 지급</p></li><li><p>단, 여행 중 공용 차량 또는 별도의 차량 임차 등이 발생하는 경우 여행일에 대한 일비의 2분의 1을 지급</p></li></ul></td></tr><tr><td><p><strong>준비금</strong></p></td><td><ul><li><p>비자발급비, 예방접종비, 여행자보험가입비, 풍토병 예방약 구입비, 법정감염병 진단검사비 등 포함</p></li><li><p>여행자보험가입비의 경우, 법인카드 결제가 불가하므로 개별 지출 후 증빙 첨부하여 여행자 계좌로 지급(본인이 직접 지출결의 진행)</p></li><li><p>나머지 준비금 비용은 모두 법인카드 결제 필수, 결제 후 본인이 직접 지출결의 진행</p></li></ul></td></tr></tbody></table><h1 id="★-국외여행-추진-절차-요약" tabindex="-1">★ 국외여행 추진 절차(요약) <a class="header-anchor" href="#★-국외여행-추진-절차-요약" aria-label="Permalink to &quot;★ 국외여행 추진 절차(요약)&quot;">​</a></h1><p><img src="'+t+'" style="width:0.13737in;height:0.13417in;"><img src="'+t+'" style="width:0.13737in;height:0.13417in;"></p><table><colgroup><col style="width:100%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>① 신 청</strong></p></th></tr></thead><tbody><tr><td><p> <strong>국외여행 계획서 제출</strong></p><ul><li><p>공지 내용에 따라 일정에 맞춰 제출(협조문 발송)</p></li><li><p>긴급 건 발생 시 내규 [별표 1]에 따른 기한 내에 국외여행 수시 신청 가능</p></li></ul></td></tr><tr><td style="text-align:center;"><p><strong>해당 부서 → 인사팀</strong></p></td></tr></tbody></table><table><colgroup><col style="width:100%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>② 심 의</strong></p></th></tr></thead><tbody><tr><td><p> <strong>정기 심의위원회 개최</strong></p><p> <strong>심의결과 부서별 통보</strong> (공문 발송)</p></td></tr><tr><td style="text-align:center;"><p><strong>인사팀(심의위원회)</strong></p></td></tr></tbody></table><p><img src="'+t+'" style="width:0.13664in;height:0.12542in;"></p><p>※ <strong>서울문화재단 여비규정</strong> 및 <strong>국외여행내규</strong>에 명시되지 않은 내용은 모두 **「공무원보수 등의 업무지침」**을 준용하며, 국외여비 사용에 대한 궁금한 점은 담당자에게 사전 문의 바랍니다.</p><table><colgroup><col style="width:100%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>③ 계획수립 및 국외여행 추진</strong></p></th></tr></thead><tbody><tr><td><p> <strong>국외여행계획 수립</strong></p><p> 국외여행계획서에 따라 <strong>국외여행 실시</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>여행자</strong></p></td></tr></tbody></table><table><colgroup><col style="width:100%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>④ 정산 및 결과보고서 완료</strong></p></th></tr></thead><tbody><tr><td><p> <strong>여비 정산</strong> 및 <strong>결과보고서</strong> 결재 완료</p><p> ERP&gt;<strong>항공마일리지 입력</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>여행자 → 인사팀</strong></p></td></tr></tbody></table><ul><li><strong>국외업무여비 지급기준표</strong> (서울문화재단 여비규정 [별표 2-2])</li></ul><p>(단위: 미불화)</p><table><colgroup><col style="width:7%;"><col style="width:7%;"><col style="width:9%;"><col style="width:22%;"><col style="width:10%;"><col style="width:21%;"><col style="width:20%;"></colgroup><thead><tr><th><p><strong>구분</strong></p></th><th style="text-align:center;"><p><strong>등급</strong></p></th><th style="text-align:center;"><p><strong>일비</strong></p></th><th style="text-align:center;"><p><strong>숙박비</strong></p></th><th style="text-align:center;"><p><strong>식비</strong></p></th><th style="text-align:center;"><p><strong>준비금</strong></p></th><th><p><strong>항공임</strong></p></th></tr></thead><tbody><tr><td rowspan="4"><p>임원</p></td><td style="text-align:center;"><p>가</p></td><td style="text-align:center;"><p>50</p></td><td style="text-align:center;"><p>실비(상한액: 389)</p></td><td style="text-align:center;"><p>160</p></td><td rowspan="4"><p>여행기간이 15일 미만인 경우 140</p></td><td rowspan="4"><p>비즈니스 클래스 (편도 5시간 미만 지역은 이코노미)</p></td></tr><tr><td style="text-align:center;"><p>나</p></td><td style="text-align:center;"><p>50</p></td><td style="text-align:center;"><p>실비(상한액: 289)</p></td><td style="text-align:center;"><p>117</p></td></tr><tr><td style="text-align:center;"><p>다</p></td><td style="text-align:center;"><p>50</p></td><td style="text-align:center;"><p>실비(상한액: 215)</p></td><td style="text-align:center;"><p>87</p></td></tr><tr><td style="text-align:center;"><p>라</p></td><td style="text-align:center;"><p>50</p></td><td style="text-align:center;"><p>실비(상한액: 161)</p></td><td style="text-align:center;"><p>73</p></td></tr><tr><td rowspan="4"><p>1급 이하</p></td><td style="text-align:center;"><p>가</p></td><td style="text-align:center;"><p>30</p></td><td style="text-align:center;"><p>실비(상한액: 176)</p></td><td style="text-align:center;"><p>81</p></td><td rowspan="4"><p>여행기간이 15일 미만인 경우 120</p></td><td rowspan="4"><p>이코노미 클래스*</p></td></tr><tr><td style="text-align:center;"><p>나</p></td><td style="text-align:center;"><p>30</p></td><td style="text-align:center;"><p>실비(상한액: 137)</p></td><td style="text-align:center;"><p>59</p></td></tr><tr><td style="text-align:center;"><p>다</p></td><td style="text-align:center;"><p>30</p></td><td style="text-align:center;"><p>실비(상한액: 106)</p></td><td style="text-align:center;"><p>44</p></td></tr><tr><td style="text-align:center;"><p>라</p></td><td style="text-align:center;"><p>30</p></td><td style="text-align:center;"><p>실비(상한액: 81</p></td><td style="text-align:center;"><p>37</p></td></tr></tbody></table><h1 id="기본-정보" tabindex="-1">기본 정보 <a class="header-anchor" href="#기본-정보" aria-label="Permalink to &quot;기본 정보&quot;">​</a></h1><ul><li><strong>국외업무여비 분류</strong></li></ul><table><colgroup><col style="width:16%;"><col style="width:83%;"></colgroup><thead><tr><th><p><strong>운임</strong></p><p>(항공, 철도, 선박, 자동차)</p></th><th><ul><li><p>실비로 품의 &amp; 지출하는 항목</p></li><li><p>여행지에서 다른 도시/국가 등으로 이동 시에만 지급되며, 시내 교통수단 이용을 위한 비용으로 지급 불가</p></li><li><p>계획 수립 및 예산 품의 시 요금에 대한 견적 증빙자료 필요</p></li><li><p>법인카드로 결제 필수, 결제 후 본인이 직접 지출결의 진행</p></li></ul></th></tr></thead><tbody><tr><td><p><strong>숙박비</strong></p></td><td><ul><li><p>출장 중 숙박하는 밤의 수에 따라 지급하며, 이동수단에서의 숙박 시 숙박비 산정 일수에서 제외</p></li><li><p>국가 및 도시등급별 상한액 있음.</p></li><li><p>법인카드로 결제 필수, 결제 후 본인이 직접 지출결의 진행</p></li></ul></td></tr></tbody></table><p>* 최근 항공사마다 비즈니스 클래스와 이코노미 클래스 사이의 프리미엄 이코노미 클래스 등이 있으나, 해당 클래스는 이코노미 클래스가 아니며 해당 좌석 구매 시 차액을 환수하게 되니 유의하시기 바랍니다.</p><h1 id="신청" tabindex="-1">신청 <a class="header-anchor" href="#신청" aria-label="Permalink to &quot;신청&quot;">​</a></h1><ul><li><strong>연간 수요조사서 제출</strong> (연 1회, 12~1월 중)</li></ul><table><colgroup><col style="width:13%;"><col style="width:86%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>목 적</strong></p></th><th><p>국외여행 예산 배분을 위한 연간 국외여행 수요 파악</p></th></tr></thead><tbody><tr><td style="text-align:center;"><p><strong>작성내용</strong></p></td><td><p>예정된 국외여행에 대한 간략한 내용(시기, 여행자, 여행지, 목적, 소요예산 등)</p></td></tr><tr><td style="text-align:center;"><p><strong>제출방법</strong></p></td><td><p>인사팀 담당자 내부메일로 제출([제출자료요청공지] 게시판 통해서 안내 예정)</p></td></tr><tr><td style="text-align:center;"><p><strong>유의사항</strong></p></td><td><ul><li><p>일정과 예산 등은 최대한 구체적으로 작성하여 제출해야 해당연도의 국외여행 수요예측이 가능합니다.</p></li><li><p>해당 수요조사서에 제출하지 않은 국외여행이더라도 긴급하게 발생한 부득이한 국외여행은 국외여행 심의 가능합니다.</p></li></ul></td></tr></tbody></table><ul><li><strong>국외여행 심의 개최 협조 요청</strong> (연 4회)</li></ul><table><colgroup><col style="width:13%;"><col style="width:86%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>목 적</strong></p></th><th><p>정기 국외여행 심의위원회 개최를 위한 안건 취합</p></th></tr></thead><tbody><tr><td><p><strong>작성내용</strong></p></td><td><p>안내된 제출자료를 협조문에 [붙임]으로 첨부</p><ul><li><p>국외여행계획서</p></li><li><p>여비산출내역서</p></li><li><p>자체점검표</p></li><li><p>여비 산출 관련 자료(항공임 및 보험료 견적, 고시환율 등)</p></li><li><p>국외여행 관련 자료(상대기관 초청장, 공문 등)</p></li></ul></td></tr><tr><td style="text-align:center;"><p><strong>제출방법</strong></p></td><td><p>인사팀으로 협조문 발송</p></td></tr><tr><td style="text-align:center;"><p><strong>유의사항</strong></p></td><td><ul><li><p>제출자료 작성 시 아래 <strong>[1-1. 자료 작성 방법]</strong>을 반드시 확인하시기 바랍니다.</p></li><li><p>협조문 최종결재자는 <u>실장</u>(본부장이 없는 부서) 또는 <u>본부장</u>입니다.</p></li></ul></td></tr></tbody></table><ul><li><strong>정식 심의일정을 놓친 경우</strong></li></ul><ul><li><p>긴급한 국외여행 발생 시, 내규에 따라 국외여행 심의위원회 개최 요청이 가능합니다.</p></li><li><p>심의위원회 개최에는 최소 10일 이상 소요되므로 인사팀과 사전 협의 및 일정 확인이 필수입니다.</p></li><li><p>정식 수요조사와 동일한 방법으로 협조문을 발송하여야 하며, 제출자료도 동일합니다.</p></li></ul><p><strong>[관련근거] 서울문화재단 국외여행내규 제4조(절차)</strong></p><p>① 임직원이 국외여행을 가고자 할 때는 [별표 1]과 같이 출발에 필요한 일정기간 전까지 [별표 2] 국외여행계획서를 작성하여, 소관부서와의 사전협의 후 국외여행 사전심의를 요청하여야 한다.</p><p><strong>[별표 1]</strong> 국외여행계획서 제출 기한</p><h1 id="_1-1-자료-작성-방법" tabindex="-1">1-1. 자료 작성 방법 <a class="header-anchor" href="#_1-1-자료-작성-방법" aria-label="Permalink to &quot;1-1. 자료 작성 방법&quot;">​</a></h1><ul><li><strong>국외여행계획서</strong></li></ul><table><colgroup><col style="width:75%;"><col style="width:24%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>작성 방법</strong></p></th><th style="text-align:center;"><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td><ul><li><p><strong><u>여행세부계획 및 일정</u></strong></p></li></ul><ul><li><p>최대한 자세하게 작성</p></li><li><p>기관 및 단체 방문&amp;미팅 시 해당 담당자 및 직책 반드시 기재</p></li></ul><ul><li><p><strong><u>여행경비</u></strong></p></li></ul><p>- 여비 산출내역서 내용을 그대로 작성</p><ul><li><p><strong><u>결과보고서, 수집자료 및 정산 확인 사실</u></strong></p></li></ul><ul><li><p>여행자의 이전 국외여행 내역 작성</p></li><li><p>내용 확인이 어려운 경우 인사팀 담당자에게 문의</p></li></ul><ul><li><p><strong><u>공무마일리지 적립 현황 및 활용 가능 여부 확인</u></strong></p></li></ul><ul><li><p>지금까지 적립한 공무 항공마일리지로 항공권 구매가 가능한지 먼저 확인 필수</p></li><li><p>사용 가능 시 항공 마일리지로 항공권 구매하는 것으로 여행경비 작성</p></li><li><p>마일리지 사용하여 항공권 구매 시 일비 50% 추가 지급 (추가 지급 일비가 항공임의 1/2을 넘을 수 없음.)</p></li></ul></td><td><p>- 지정양식 (국외여행내규 [별표 2])</p></td></tr></tbody></table><ul><li><strong>여비산출내역서</strong></li></ul><table><colgroup><col style="width:75%;"><col style="width:24%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>작성 방법</strong></p></th><th style="text-align:center;"><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td><ul><li><p><strong><u>공통</u></strong></p></li></ul><ul><li><p>국외여행 주관(초청)기관, 관련사 등이 경비의 전액 또는 일부를 부담하는 경우 해당 항목을 제외한 여비를 지급하며, 재단 예산(업무추진비 등)으로 간담회 등의 식대를 추가 품의할 경우 여비 중 식비 지급에서 제외</p></li></ul><p>(예시) 초청기관에서 항공권 지원 시 ▶ 숙박비, 일비, 식비, 준비금만</p><p>재단 예산으로 부담</p><ul><li><p>원화 환율을 적용하여 산출한 원화 금액은 일의자리 숫자를 절사하여 십원 단위로 산정</p></li><li><p>여행사 사용 지양(여행사 수수료 지급 이슈)해야 하며, 부득이한 사정이 있을 경우 사전 인사팀과 협의 필수</p></li></ul><ul><li><p><strong><u>시트 1</u></strong></p></li></ul><ul><li><p>여행자별로 작성(여행자가 2인 이상일 경우 시트 추가)</p></li><li><p>도시 간 이동 있을 경우, 행 추가하여 철도 운임 등 추가 작성</p></li></ul><ul><li><p><strong><u>시트 2</u></strong></p></li></ul><ul><li><p>항공(선박) 이동으로 식사가 없을 경우, 1식 당 ‘0.33’만큼 제외</p></li><li><p>항공(선박) 이동으로 지상 숙박이 없을 경우, 해당일은 ‘0’으로 작성</p></li><li><p>여행자별 일정이 다른 경우 시트 2도 여행자별 작성</p></li></ul></td><td><ul><li><p>공연관람비, 간담회 등 비용은 국외업무여비로 사용 불가</p></li><li><p>항공임 2천만원 이상은 경쟁입찰에 해당</p></li></ul></td></tr></tbody></table><table><colgroup><col style="width:35%;"><col style="width:41%;"><col style="width:23%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>비자의 여부</strong></p></th><th style="text-align:center;"><p><strong>제출 기한</strong></p></th><th style="text-align:center;"><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p>비자가 필요한 나라</p></td><td style="text-align:center;"><p>출국예정일로부터 30일 전</p></td><td rowspan="2"><p>준비 기간 포함</p></td></tr><tr><td style="text-align:center;"><p>비자가 필요 없는 나라</p></td><td style="text-align:center;"><p>출국예정일로부터 20일 전</p></td></tr></tbody></table><ul><li><strong>자체점검표</strong></li></ul><table><colgroup><col style="width:75%;"><col style="width:24%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>작성 방법</strong></p></th><th style="text-align:center;"><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td><ul><li><p>□ 칸에 검토결과를 표시</p></li><li><p>마지막 행에는 실장(본부장이 없는 부서) 또는 본부장의 검토의견 작성</p></li><li><p>여행자 및 검토자의 확인 서명 날인 필수</p></li></ul></td><td><p>- 지정양식</p><p>(p.10 [별첨 1] 참고)</p></td></tr></tbody></table><ul><li><strong>여비 산출 관련 자료</strong></li></ul><table><colgroup><col style="width:14%;"><col style="width:60%;"><col style="width:24%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>작성 방법</strong></p></th><th style="text-align:center;"><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p><strong>항공임 견적</strong></p></td><td><ul><li><p>항공사는 정해져있지 않으나, 여행경비 절감을 위해 노력해야 함.</p></li><li><p>여행일정에 대한 항공권 가격이 나온 캡쳐본 등을 제출</p></li><li><p>협조문 제출 당시 제출한 항공임과 실제 품의 시 항공권 금액은 변동될 수 있으나, 승인 시의 금액보다 큰 경우에는 예산 부족 이슈 등이 발생할 수 있으니 인사팀과 협의 필요</p></li></ul></td><td style="text-align:left;"><p>- 항공임의 경우 가격이 큰 폭으로 변동되므로 여행 승인 후 최대한 빠르게 결제 완료 요망</p></td></tr><tr><td style="text-align:center;"><p><strong>보험료 견적</strong></p></td><td><ul><li><p>여행일정에 대한 보험료가 나온 캡쳐본 등 제출</p></li><li><p>협조문 제출 당시 제출한 보험료와 실제 품의 시 보험료 금액은 변동될 수 있음.</p></li></ul></td><td style="text-align:left;"><p>- 제출 시 개인정보 (성명, 생년월일) 노출되지 않도록 주의</p></td></tr><tr><td style="text-align:center;"><p><strong>고시환율</strong></p></td><td><ul><li><p>국외여행계획 작성일의 달러 환율(최초고시)의 현찰매도율 (현찰 살 때)을 기준으로 하고, 소수점 아랫자리는 절사</p></li><li><p>환율 확인 방법: 하나은행 홈페이지</p></li></ul><p><u>https://<a href="http://www.kebhana.com/cont/mall/mall15/mall1501/index.jsp?_menuNo=23100">www.kebhana.com/cont/mall/mall15/mall1501/index.jsp?_menuNo=23100</a></u></p><ul><li><p>달러 환율이 나온 캡쳐본 제출</p></li></ul><p>(예시)</p></td><td style="text-align:left;"></td></tr><tr><td style="text-align:center;"><p><strong>상대기관 초청장 등</strong></p></td><td><ul><li><p>초청에 따른 국외여행 시에는 초청장 등을 함께 제출</p></li><li><p>초청장에는 여행자의 업무 수행 내용, 초청기관에서 부담하는 경비 등이 포함되는 것이 바람직함</p></li></ul></td><td style="text-align:left;"><p>- 초청 건임에도 해당 내용이 없을 경우 예산 검토가 어려우며, 구술심의 추가 진행 필요</p></td></tr></tbody></table><ol start="2"><li><p>심의</p><ul><li><strong>심의위원회 개최</strong></li></ul></li></ol><p>- 예정 일정에 따라 국외여행 심의위원회를 개최하며, 심의위원회는 내/외부위원으로 구성됩니다.</p><ul><li><strong>심의 기준(항목)</strong></li></ul><table><colgroup><col style="width:7%;"><col style="width:24%;"><col style="width:58%;"><col style="width:8%;"></colgroup><thead><tr><th><p><strong>심의 항목</strong></p></th><th style="text-align:center;"><strong>심 의 지 표</strong></th><th style="text-align:center;"><p><strong>심 의 내 용</strong></p></th><th style="text-align:center;"><p><strong>가중치</strong></p></th></tr></thead><tbody><tr><td rowspan="6"><p>여행 계획</p></td><td style="text-align:center;"><p>여행 목적 타당성</p></td><td><p>- 여행의 필요성 및 중요성 검토</p></td><td style="text-align:center;"><p>20</p></td></tr><tr><td style="text-align:center;"><p>여행 지역의 적정성</p></td><td><p>- 여행목적의 부합여부, 일정의 충실성, 사전협의 구체성</p></td><td style="text-align:center;"><p>20</p></td></tr><tr><td style="text-align:center;"><p>여행자 및 인원 적절성</p></td><td><p>- 여행자 담당업무, 여행단 규모 및 업무분장 명확성</p></td><td style="text-align:center;"><p>20</p></td></tr><tr><td style="text-align:center;"><p>일정 및 시기 적정성</p></td><td><p>- 여행기간 적정성, 불필요한 일정 및 이동유무</p></td><td style="text-align:center;"><p>10</p></td></tr><tr><td style="text-align:center;"><p>여행경비 적정성</p></td><td><p>- 비용 산출 및 지원의 적정성, 예산절감 노력</p></td><td style="text-align:center;"><p>10</p></td></tr><tr><td style="text-align:center;"><p>여행 결과의 활용가능성</p></td><td><p>- 여행 결과 활용 가능성의 명확 여부</p></td><td style="text-align:center;"><p>20</p></td></tr><tr><td colspan="2" rowspan="2"><p>행정 사항(감점)</p></td><td><p>- 제출기한 지연, 증빙자료 누락의 경우 감점 (-5점)</p></td><td style="text-align:center;"></td></tr><tr><td><p>- 이전 결과보고서 제출 지연의 경우 감점 (-5점)</p></td><td style="text-align:center;"></td></tr><tr><td colspan="3" style="text-align:center;"><p><strong>합 계</strong></p></td><td style="text-align:center;"><p><strong>100</strong></p></td></tr></tbody></table><ul><li><strong>심의 의결</strong></li></ul><ul><li><p>심의위원회는 상기 기준에 따라 여행계획 및 여비 등 검토하며, 필요 시에는 여행자가 직접 출석하여 구술심의를 추가로 진행할 수 있습니다.</p></li><li><p>심의위원별 합산 점수가 80점 이상일 경우 ‘가결’, 80점 미만일 경우 ‘부결’로 출석위원 과반수의 결정으로 의결합니다.</p><ul><li><strong>심의 결과 통보</strong></li></ul></li></ul><ul><li><p>심의 결과는 부서별 공문으로 통보합니다.</p></li><li><p>‘조건부 가결’ 건의 경우, 별도의 조건을 명시하여 통보하며 해당 조건을 충족하도록 계획을 수정할 경우 국외여행을 승인합니다.</p></li></ul><h1 id="국외여행계획-수립-및-추진" tabindex="-1">국외여행계획 수립 및 추진 <a class="header-anchor" href="#국외여행계획-수립-및-추진" aria-label="Permalink to &quot;국외여행계획 수립 및 추진&quot;">​</a></h1><ul><li><strong>국외여행계획 수립</strong></li></ul><table><colgroup><col style="width:75%;"><col style="width:24%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>작성 방법</strong></p></th><th style="text-align:center;"><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td><ul><li><p>신청 시 제출한 ‘국외여행계획서’를 활용하되, 해당 자료 내용 중 미비했던 부분(세부일정, 방문기관, 담당자 등)은 더 구체적으로 작성 가능하여 상신</p></li><li><p>국외여행계획은 공개가 원칙(공개 불가한 내용은 전자문서 작성 시 형광펜 (비공개) 처리</p></li><li><p>부득이한 사유로 여행자, 여행기간 및 시기 등이 변경될 경우에는 사전 인 사팀과 협의 필수이며, 국외여행내규 [별표 5] 양식을 작성하여 인사팀으 로 협조문 발송(결재라인: 실/본부장 전결)</p></li><li><p>환율은 국외여행 신청 시의 환율을 동일하게 적용해야 하며, 항공임 및 보 험료 등 가격 변동이 있을 시 변동된 금액으로 계획 수립</p></li><li><p>국외여행계획서 내 품의 포함여부</p></li></ul><ul><li><p>포함 가능하나, 문서 결재 완료 후 금액 변동 시 품의증감 필요</p></li><li><p>포함하지 않을 경우, 문서 결재 완료 후 품의 기안 별도 상신 필요 (결재라인에 국외여행 담당자 협조 결재자로 추가)</p></li></ul><ul><li><p>결재라인: 여행자 &gt; 부서장(검토) &gt; 국외여행(협조) &gt; 복무(협조) &gt; 추산(협조)</p><ul><li><p>인사팀장(협조) &gt; 실장(검토) &gt; 본부장(검토) &gt; 윤리경영실장(협조)</p></li><li><p>대표이사(결재)</p></li></ul></li></ul></td><td><p>- 국외여비 품의 및 예산 사용 중 명확하지 않은 부분은 국외여행 담당자와 상의 후 진행 필수 (오사용 후 수습이 어려울 수 있음.)</p></td></tr></tbody></table><ul><li><strong>여비 결제 및 지급 방법</strong></li></ul><table><colgroup><col style="width:13%;"><col style="width:86%;"></colgroup><thead><tr><th><p><strong>항공권</strong></p></th><th><ul><li><p>여행사 항공권의 경우 발권수수료가 발생하기 때문에 항공사에 직접 결제해야 함.</p></li><li><p>항공마일리지는 개별 적립하여 추후 보고(필수, 미 적립 시 사후 적립)</p></li><li><p>여행사 항공권 구매가 필요한 경우 인사팀과 사전 협의 필수</p></li></ul></th></tr></thead><tbody><tr><td><p><strong>숙박비</strong></p></td><td><ul><li><p><u>법인카드</u>로 결제 후 본인이 직접 지출결의 진행</p></li><li><p>매입환율 적용 및 카드결제수수료 등을 포함하여 여비지급기준표에 명시된 상한액이 넘지 않도록 유의</p></li></ul></td></tr><tr><td><p><strong>일비, 식비</strong></p></td><td><ul><li><p>여행자 계좌로 입금하는 지출결의를 본인이 직접 진행</p></li><li><p>여행자가 여러 명일 경우 한 명이 전체 일비, 식비 지급 관련 지출결의 상신 가능</p></li><li><p>여행 전 지급하는 것이 일반적이나, 상황에 따라 여행 후 정산 지급 가능</p></li><li><p>지급 완료 후 여행 내용 변경 등으로 일부 금액 반납이 필요한 경우, 인사팀 및 재무 회계팀 담당자와 논의 후 처리</p></li></ul></td></tr><tr><td><p><strong>보험료</strong></p></td><td><ul><li><p>개인에 대한 여행자보험은 해당자 명의의 카드로만 결제 가능</p></li><li><p>개인 카드 결제 후 증빙자료(견적, 지출내역 등)를 첨부하여 여행자 계좌로 무통장입금 지출결의를 직접 진행</p></li></ul></td></tr><tr><td><p><strong>그 외 준비금</strong></p></td><td><ul><li><p>비자발급비, 예방접종비 등은 법인카드로 결제 후 본인이 직접 지출결의 진행</p></li><li><p>비자발급비, 예방접종 또는 법정감염병 진단검사비 등은 필수인 국가에 한하여만 품의 &amp;지출 가능</p></li></ul></td></tr></tbody></table><ul><li><strong>복무 관리</strong></li></ul><table><colgroup><col style="width:13%;"><col style="width:86%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>여행 전</strong></p></th><th><ul><li><p>ERP &gt; 근무상황부 &gt; ‘국외출장’ 상신</p></li><li><p>국외여행은 시간외근무 인정 불가</p></li></ul></th></tr></thead><tbody><tr><td style="text-align:center;"><p><strong>여행 후</strong></p></td><td><ul><li><p>출퇴근시간은 결과보고 내용을 토대로 복무 담당자가 일괄 입력 (근태소명 X)</p></li></ul></td></tr></tbody></table><h1 id="국외여행-결과보고" tabindex="-1">국외여행 결과보고 <a class="header-anchor" href="#국외여행-결과보고" aria-label="Permalink to &quot;국외여행 결과보고&quot;">​</a></h1><ul><li><strong>국외여행 결과보고서 작성</strong></li></ul><ul><li><p>결과보고 문서는 공개 원칙(공개 불가한 내용은 전자문서 작성 시 형광펜(비공개) 처리</p></li><li><p><strong><u>국외여행 개요</u></strong></p></li></ul><p>- 여행 기간 및 소요경비가 계획 수립 시와 다른 경우, 실제 여행 기간 및 소요경비로 작성</p><ul><li><strong><u>여행세부내용</u></strong></li></ul><ul><li><p>여행일정별 방문지 및 방문기관은 실제 여행 일정 및 결과에 따라 작성</p></li><li><p>수행성과는 방문 및 미팅 내용, 증빙사진 등을 첨부하여 충실하게 작성</p></li><li><p>국외여행 결과에 따른 향후 사업 반영 및 환류 계획 등 작성</p></li></ul><ul><li><strong><u>여행경비 정산</u></strong></li></ul><ul><li><p>예정수행 성과와 증빙사진 첨부 등 관련 내용을 충실하게 작성</p></li><li><p>산출내역은 실사용액에 대한 산출내역으로 작성</p></li><li><p>사용내역이 없는 행(비자발급비, 교통비-기타 등)은 삭제</p></li></ul><ul><li><strong><u>공무마일리지 적립 보고</u></strong></li></ul><ul><li><p>두 개 이상 항공사 마일리지 적립 시 행 구분하여 작성</p></li><li><p>마일리지 적립이 발생하지 않은 저가항공사의 경우는 ‘발생 마일리지 없음’으로 작성</p></li></ul><ul><li><p><strong><u>결재라인</u></strong>: 여행자 &gt; 부서장(검토) &gt; 국외여행(협조) &gt; 복무(협조) &gt; 인사팀장(협조) &gt; 실장(검토)</p><ul><li>본부장(검토) &gt; 대표이사(결재)</li></ul></li></ul><p><strong>작성 방법</strong></p><p>※ 귀국일로부터 **<u>30일 이내에 결재 완료</u>**되어야 하며, 결재 완료 시점이 귀국일로부터 30일이 지난 경우 지연 제출로 분류되어 해당자의 향후 국외여행 신청 및 **<u>심의 시 5점 감점</u>**됩니다.</p><ul><li><strong>항공마일리지 등록</strong></li></ul><ul><li><p>국외여행 결과보고서 결재 후 해당 국외여행으로 발생한 항공 마일리지를 ERP에 등록합니다. ( 메뉴 <strong>[항공마일리지관리]</strong> &gt; <strong>[추가]</strong> 버튼 클릭하여 새로운 행 생성 &gt; 작성 완료 후 <strong>[저장]</strong> )</p></li><li><p>반드시 <strong><u>본인이 작성</u></strong> 바랍니다. (타인이 작성하는 경우, 향후 본인 마일리지 확인 불가)</p></li><li><p>작성 완료 후 국외여행 담당자에게 확인 요청을 해주셔야 하며, 담당자 검토 후 문제없을 시 ‘마감’ 처리합니다.</p></li></ul><p><strong>[별첨 1]</strong> 국외여행 자체점검표 양식</p><p><img src="'+s+'" style="width:4.79124in;height:0.75667in;"></p><p><strong>국외여행 자체점검표</strong></p><p>여행자:</p><p>(서명)</p><p>(서명)</p><p>확인자:</p><p>(서명)</p><ul><li><p><strong>건명 : 0000 00000 00을 위한 국외여행</strong></p></li><li><p><strong>여행자(부서) : 000(00000팀)</strong></p></li><li><p><strong>방문국(도시) : 0000(0000)</strong></p></li><li><p><strong>여행기간 : 0000년 00월 00일(0요일) ~ 0000년 00월 00일(0요일)</strong></p></li><li><p><strong>경비부담 :</strong></p></li></ul><ul><li><strong><u>출장년월</u></strong>: 시작일 기준으로 기재</li></ul><ul><li><p><strong><u>성명, 부서, 직급</u></strong>: 여행자 본인의 정보에 맞게 작성</p></li><li><p><strong><u>출장지, 출장시작일, 출장종료일</u></strong>: 국외여행 여행지, 기간에 맞게 작성</p></li><li><p><strong><u>출장내역</u></strong>: 국외여행 건명 작성</p></li><li><p><strong><u>총경비(집행)</u></strong>: 소요된 국외여비 총액 작성</p></li><li><p><strong><u>결과보고</u></strong>: 국외여행 결과보고 결재일자</p></li><li><p><strong><u>항공임, 일비, 식비, 숙박비</u></strong>: 소요된 항목별 국외여비 금액 작성</p></li><li><p><strong><u>준비비</u></strong>: 소요된 준비금 총액 작성</p></li><li><p><strong><u>기타</u></strong>: 그 외 소요된 금액이 있으면 작성하며, 없을 경우 공란 처리</p></li><li><p><strong><u>문서번호</u></strong>: 국외여행 결과보고의 문서번호(예: 인사팀-000호)</p></li><li><p><strong><u>마일리지, 항공사</u></strong></p></li></ul><ul><li><p>적립한 마일리지와 해당 항공사 작성</p></li><li><p>국외여행 한 건 당 <u>두 개 항공사 이상의 마일리지 적립</u>이 있는 경우, <u>행 추가 및 구분</u>하여 작성</p></li><li><p>모든 내용은 동일하게 작성하며, 마일리지&amp;항공사만 다르게 작성</p></li></ul><ul><li><strong><u>작성자</u></strong>: 공란으로 두며, 저장 시 작성자 성명으로 기재됨</li></ul><p><strong>작성 방법</strong></p><p>(예시) 국외여행 기간이 2024.7.31.~8.3.인 경우 ▶ 출장년월: 2024/7</p><table><colgroup><col style="width:14%;"><col style="width:61%;"><col style="width:2%;"><col style="width:3%;"><col style="width:4%;"><col style="width:12%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>항 목</strong></p></th><th colspan="5"><p><strong>검 토 결 과 (□√ 표 시 )</strong></p></th></tr></thead><tbody><tr><td></td><td rowspan="5"><ul><li><p><strong>국외여행 이외 수단으로 해당 업무 수행이 불가한가</strong></p></li></ul><p>- 불가사유 :</p><ul><li><p><strong>여행목적 수행에 필요한 기관 및 장소를 방문하는가</strong></p></li><li><p><strong>최근 3년간 동일한 목적으로 해당 기관을 방문하였는가</strong></p></li><li><p><strong>출 장 목 적 에 맞 는 세 부 계 획 이 수 립 되 었 는 가</strong></p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아 니 오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>여행목적 및</strong></p></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;"><p><strong>여행지역의</strong></p></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>적 정 성</strong></p></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>및 타당성</strong></p></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:left;"><p><strong>여행자 및 인 원 의 적 절 성</strong></p></td><td><ul><li><p><strong>여행인원 및 여행자의 담당 업무가 여행 목적에 적합한가</strong></p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>일 정 및</strong></p></td><td><ul><li><p><strong>국외여행 목적에 필요한 적정 기간을 책정했는가</strong></p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>시 기 와</strong></p></td><td><ul><li><p><strong>불필요한 일정(관광 등) 또는 도시 간 이동이 포함되어 있는가</strong></p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>경 비 의</strong></p></td><td><ul><li><p><strong>평 일 최 소 1 개 기 관 이 상 방 문 하 는 가</strong></p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>적 정 성</strong></p></td><td><ul><li><p><strong>출장 경비의 산 정이 적정한 가</strong> ( 항 공 료 및 여 비 )</p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td><p><strong>여행 결과 활용가능성</strong></p></td><td><ul><li><p><strong>국외여행 결과를 활용할 구체적인 방안이 있는가</strong></p></li></ul></td><td style="text-align:center;"><strong>:</strong></td><td style="text-align:center;"><p><strong>예</strong></p></td><td style="text-align:center;"><strong>□</strong></td><td style="text-align:center;"><p><strong>아니오 □</strong></p></td></tr><tr><td><p><strong>실/본부장 검토의견</strong></p></td><td colspan="5"></td></tr></tbody></table>',81)]))}const x=e(o,[["render",g]]);export{h as __pageData,x as default};
